@keyframes quanta-fade {
    from { opacity: 0; }
    to { opacity: 1; }
}
.animate-fade {
    animation: quanta-fade 0.5s ease-in-out both;
}

@keyframes quanta-slide-up {
    from { transform: translateY(20px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}
.animate-slide-up {
    animation: quanta-slide-up 0.5s ease-out both;
}

@keyframes quanta-slide-down {
    from { transform: translateY(-20px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}
.animate-slide-down {
    animation: quanta-slide-down 0.5s ease-out both;
}

@keyframes quanta-slide-left {
    from { transform: translateX(20px); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
}
.animate-slide-left {
    animation: quanta-slide-left 0.5s ease-out both;
}

@keyframes quanta-slide-right {
    from { transform: translateX(-20px); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
}
.animate-slide-right {
    animation: quanta-slide-right 0.5s ease-out both;
}

@keyframes quanta-bounce {
    0%, 100% {
        transform: translateY(0);
        animation-timing-function: ease-in;
    }
    50% {
        transform: translateY(-25%);
        animation-timing-function: ease-out;
    }
}
.animate-bounce {
    animation: quanta-bounce 1s infinite;
}

/* New Quanta Animations */

@keyframes quanta-spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}
.animate-spin {
    animation: quanta-spin 1s linear infinite;
}

@keyframes quanta-pulse {
    0% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.05); opacity: 0.7; }
    100% { transform: scale(1); opacity: 1; }
}
.animate-pulse {
    animation: quanta-pulse 1.5s ease-in-out infinite;
}

@keyframes quanta-shake {
    0%, 100% { transform: translateX(0); }
    20%, 60% { transform: translateX(-10px); }
    40%, 80% { transform: translateX(10px); }
}
.animate-shake {
    animation: quanta-shake 0.8s ease-in-out both;
}

@keyframes quanta-wiggle {
    0%, 100% { transform: rotate(0deg); }
    15% { transform: rotate(5deg); }
    30% { transform: rotate(-5deg); }
    45% { transform: rotate(3deg); }
    60% { transform: rotate(-3deg); }
    75% { transform: rotate(2deg); }
}
.animate-wiggle {
    animation: quanta-wiggle 1s ease-in-out both;
}

@keyframes quanta-zoom-in {
    from { transform: scale(0.5); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
}
.animate-zoom-in {
    animation: quanta-zoom-in 0.5s ease-out both;
}

@keyframes quanta-zoom-out {
    from { transform: scale(1.2); opacity: 1; }
    to { transform: scale(1); opacity: 0; }
}
.animate-zoom-out {
    animation: quanta-zoom-out 0.5s ease-in both;
}

@keyframes quanta-heartbeat {
    0%, 40%, 80%, 100% { transform: scale(1); }
    20%, 60% { transform: scale(1.2); }
}
.animate-heartbeat {
    animation: quanta-heartbeat 1.2s ease-in-out infinite;
}

@keyframes quanta-ping {
    0% { transform: scale(1); opacity: 1; }
    75% { transform: scale(2); opacity: 0; }
    100% { transform: scale(2); opacity: 0; }
}
.animate-ping {
    animation: quanta-ping 1s cubic-bezier(0, 0, 0.2, 1) infinite;
}

