/* -----------------------------------------------------------------------------
   12. Transitions & Animation
----------------------------------------------------------------------------- */
/* Transition Property */
.transition-none      { transition-property: none; }
.transition-all       { transition-property: all; }
.transition-colors    { transition-property: color, background-color, border-color, text-decoration-color, fill, stroke; }
.transition-opacity   { transition-property: opacity; }
.transition-shadow    { transition-property: box-shadow; }
.transition-transform { transition-property: transform; }

/* Transition Duration */
.duration-75   { transition-duration: 75ms; }
.duration-150  { transition-duration: 150ms; }
.duration-300  { transition-duration: 300ms; }
.duration-500  { transition-duration: 500ms; }
.duration-700  { transition-duration: 700ms; }
.duration-1000 { transition-duration: 1000ms; }

/* Transition Timing Function */
.ease-linear      { transition-timing-function: linear; }
.ease-in          { transition-timing-function: cubic-bezier(0.4,0,1,1); }
.ease-out         { transition-timing-function: cubic-bezier(0,0,0.2,1); }
.ease-in-out      { transition-timing-function: cubic-bezier(0.4,0,0.2,1); }

/* Keyframes + Animate */

@keyframes fade     { from { opacity: 0; } to { opacity: 1; } }

@keyframes slide-in { from { transform: translateY(10px); } to { transform: translateY(0); } }

@keyframes spin     { to { transform: rotate(360deg); } }

.animate-none       { animation: none; }
.animate-fade       { animation: fade 300ms ease-out both; }
.animate-slide-in   { animation: slide-in 500ms ease-out both; }
.animate-spin       { animation: spin 1s linear infinite; }


