.quanta-accordion {
  display: flex;
  flex-direction: column;
  gap: var(--quanta-space-4);
  width: 100%;
}

/* ─── Base Item ───────────────────────── */
.quanta-accordion-item {
  overflow: hidden;
  transition: box-shadow var(--quanta-duration-fast) var(--quanta-ease-default);
}

/* ─── Header ──────────────────────────── */
.quanta-accordion-header {
  width: 100%;
  padding: var(--quanta-space-4);
  font-family: var(--quanta-font-sans);
  font-size: var(--quanta-body-size);
  color: var(--quanta-text-default);
  background-color: var(--white);
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  user-select: none;
  transition: background-color var(--quanta-duration-fast), color var(--quanta-duration-fast);
  border: none;
}

.quanta-accordion-header .icon {
  transition: transform var(--quanta-duration-fast);
}

.quanta-accordion-header[aria-expanded="true"] .icon {
  transform: rotate(180deg);
}

/* ─── Content ─────────────────────────── */
.quanta-accordion-content {
  max-height: 0;
  overflow: hidden;
  padding: 0 var(--quanta-space-6);
  transition: max-height var(--quanta-duration-normal) var(--quanta-ease-default),
              padding var(--quanta-duration-fast);
}

.quanta-accordion-content[aria-hidden="false"] {
  padding: var(--quanta-space-4);
  max-height: 100vh;
}

/* ─── Card Style ───────────────────────── */
.quanta-accordion.card .quanta-accordion-item {
  background-color: var(--white);
  border-radius: var(--quanta-rounded-lg);
  box-shadow: var(--quanta-shadow-md);
}

.quanta-accordion.card .quanta-accordion-item:hover {
  box-shadow: var(--quanta-shadow-lg);
}

.quanta-accordion.quanta-accordion-outline{
  background: transparent;
}

/* ─── Block Style ──────────────────────── */
.quanta-accordion.block .quanta-accordion-item {
  border-radius: 0;
  border: none;
  background-color: transparent;
  box-shadow: none;
  border-bottom: 2px solid var(--quanta-border-color);
}

.quanta-accordion.block .quanta-accordion-header {
  background: transparent;
  padding-left: 0;
  padding-right: 0;
}

.quanta-accordion.block .quanta-accordion-content {
  padding-left: 0;
  padding-right: 0;
}

/* ─── Outline Style ────────────────────── */
.quanta-accordion.quanta-accordion-outline .quanta-accordion-item {
  border: 2px solid var(--quanta-border-color);
  border-radius: var(--quanta-rounded-md);
  background: transparent;
}

/* ─── Dark Mode ───────────────────────── */
html[data-theme="dark"] {
  .quanta-accordion.card .quanta-accordion-item {
    background-color: var(--quanta-slate-800);
    color: var(--quanta-text-default);
  }

  .quanta-accordion-header, .quanta-accordion-content {
    background-color: transparent;
    color: var(--quanta-text-default);
  }

  .quanta-accordion.quanta-accordion-outline .quanta-accordion-item {
    border-color: var(--quanta-border-color);
  }
}

/* ─── Responsive ───────────────────────── */

@media (min-width: var(--quanta-screen-md)) {
  .quanta-accordion-header {
    padding: var(--quanta-space-6);
    font-size: var(--quanta-text-lg);
  }

  .quanta-accordion-content {
    padding-left: var(--quanta-space-6);
    padding-right: var(--quanta-space-6);
  }

  .quanta-accordion-content[aria-hidden="false"] {
    padding-top: var(--quanta-space-5);
    padding-bottom: var(--quanta-space-6);
  }
}

/* Base Alert */
.quanta-alert {
  display: flex;
  align-items: center;
  gap: var(--quanta-space-2);
  padding: var(--quanta-space-2);
  border-radius: var(--quanta-rounded-md);
  font-size: var(--quanta-text-base);
  font-family: var(--quanta-font-secondary);
  font-weight: 500;
  line-height: var(--quanta-leading-normal);
  border: var(--quanta-border-width) solid transparent;
  background-color: var(--quanta-bg-default);
  color: var(--quanta-text-default);
  box-shadow: var(--quanta-shadow-sm);
  transition:
    background-color var(--quanta-duration-fast),
    box-shadow var(--quanta-duration-fast);
  width: 100%;
}

.quanta-alert:hover {
  box-shadow: var(--quanta-shadow);
}

.quanta-alert svg {
  flex-shrink: 0;
}

/* ── Alert Variants ───────────────────────────── */
.quanta-alert-primary {
  background-color: var(--quanta-primary);
  color: var(--quanta-text-primary);
  border: 1px solid var(--quanta-border-primary);
}

.quanta-alert-info {
  background-color: var(--quanta-bg-info);
  color: var(--quanta-text-info);
  border: 1px solid var(--quanta-border-info);
}

.quanta-alert-success {
  background-color: var(--quanta-bg-success);
  color: var(--quanta-text-success);
  border: 1px solid var(--quanta-border-success);
}

.quanta-alert-warning {
  background-color: var(--quanta-bg-warning);
  color: var(--quanta-text-warning);
  border: 1px solid var(--quanta-border-warning);
}

.quanta-alert-error {
  background-color: var(--quanta-bg-danger);
  color: var(--quanta-text-danger);
  border: 1px solid var(--quanta-border-danger);
}

.quanta-alert-neutral {
  background-color: var(--quanta-bg-neutral);
  color: var(--quanta-text-neutral);
  border: 1px solid var(--quanta-border-neutral);
}

.quanta-alert-accent {
  background-color: var(--quanta-bg-accent);
  color: var(--quanta-text-accent);
  border: 1px solid var(--quanta-border-accent);
}

/* ── Responsive Padding & Widths ──────────────── */

@media (min-width: var(--quanta-screen-md)) {
  .quanta-alert {
    padding: var(--quanta-space-3);
    width: 90%;
  }
}

@media (min-width: var(--quanta-screen-lg)) {
  .quanta-alert {
    padding: var(--quanta-space-4);
    width: 80%;
  }
}

@media (min-width: var(--quanta-screen-xl)) {
  .quanta-alert {
    width: 70%;
  }
}

.quanta-avatar {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  border-radius: var(--quanta-rounded-full);
  font-weight: 600;
  color: var(--white);
  text-transform: uppercase;
  font-family: var(--quanta-font-secondary);
  overflow: hidden;
  position: relative;
  object-fit: cover;
}

.quanta-avatar-wrapper {
  display: inline-block;
  position: relative;
}

/* ─── Semantic Background Variants ───────────────────────── */
.quanta-avatar-primary  { background-color: var(--quanta-primary); color: var(--white); }
.quanta-avatar-success  { background-color: var(--quanta-bg-success); color: var(--white); }
.quanta-avatar-danger   { background-color: var(--quanta-bg-danger);  color: var(--white); }
.quanta-avatar-warning  { background-color: var(--quanta-bg-warning); color: var(--white); }
.quanta-avatar-info     { background-color: var(--quanta-bg-info);    color: var(--white); }
.quanta-avatar-secondary { background-color: var(--quanta-bg-secondary); color: var(--white); }
.quanta-avatar-light    { background-color: var(--quanta-grey-100); color: var(--quanta-grey-800); }
.quanta-avatar-dark     { background-color: var(--quanta-slate-800); color: var(--white); }

/* ─── Dark Mode Adaptations ─────────────────────────────── */
html[data-theme="dark"] {
  .quanta-avatar-light { background-color: var(--quanta-grey-200); color: var(--quanta-grey-900); }
  .quanta-avatar-dark  { background-color: var(--quanta-grey-900); color: var(--white); }
}


/* Sizes from 20px (sm) to 80px (2xl) */
.quanta-avatar-sm  { width: 20px; height: 20px; font-size: 10px; }
.quanta-avatar-md  { width: 32px; height: 32px; font-size: 14px; }
.quanta-avatar-lg  { width: 48px; height: 48px; font-size: 18px; }
.quanta-avatar-xl  { width: 64px; height: 64px; font-size: 22px; }
.quanta-avatar-2xl { width: 80px; height: 80px; font-size: 26px; }

/* Group support */
.quanta-avatar-group {
  display: flex;
