  display: flex;
  align-items: center;
  justify-content: center;
}

.quanta-avatar-dot {
  position: absolute;
  bottom: 2px;
  right: -2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--quanta-white);
