.quanta-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--quanta-space-4);
  width: 100%;
  align-items: stretch;
  justify-content: center;
}

.quanta-gallery-item {
  position: relative;
  overflow: hidden;
  border-radius: var(--quanta-rounded-md);
  aspect-ratio: 1 / 1;
  background: var(--quanta-bg-muted);
  cursor: pointer;
  transition: transform 0.2s ease;
}

.quanta-gallery-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.3s ease;
}

.quanta-gallery-item:hover img,
.quanta-gallery-item:focus-visible img {
  transform: scale(1.05);
}

/* Lightbox */
.quanta-lightbox {
  display: none;
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(4px);
  align-items: center;
  justify-content: center;
  z-index: 10000;
  padding: var(--quanta-space-4);
}

.quanta-lightbox.active {
  display: flex;
}

.quanta-lightbox img {
  max-width: 100%;
  max-height: 90vh;
  border-radius: var(--quanta-rounded-md);
  box-shadow: 0 0 0 3px var(--quanta-bg-default);
}

.quanta-lightbox-close {
  position: absolute;
  top: var(--quanta-space-4);
  right: var(--quanta-space-4);
  font-size: var(--quanta-text-2xl);
  color: #fff;
  cursor: pointer;
  background: rgba(0, 0, 0, 0.4);
  border-radius: 50%;
  padding: 0.5rem 0.75rem;
  transition: background 0.2s;
}

.quanta-lightbox-close:hover {
  background: rgba(0, 0, 0, 0.8);
}

/* Responsive tweaks */

@media (max-width: 640px) {
  .quanta-gallery {
    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
    gap: var(--quanta-space-2);
  }
}

html[data-theme="dark"] .quanta-gallery-item {
  background: var(--quanta-bg-emphasis);
}

html[data-theme="dark"] .quanta-lightbox img {
  box-shadow: 0 0 0 3px var(--quanta-bg-emphasis);
}

.quanta-grid {
  display: grid;
}

/* Basic columns */
.grid-cols-1 { grid-template-columns: repeat(1, 1fr); }
.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid-cols-4 { grid-template-columns: repeat(4, 1fr); }
.grid-cols-5 { grid-template-columns: repeat(5, 1fr); }
.grid-cols-6 { grid-template-columns: repeat(6, 1fr); }

/* Auto-fit */
.grid-auto-fit {
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

/* Gaps */
.gap-2 { gap: var(--quanta-space-2); }
.gap-4 { gap: var(--quanta-space-4); }
.gap-6 { gap: var(--quanta-space-6); }

/* Responsive modifiers */

@media (min-width: 640px) {
  .sm-grid-cols-1 { grid-template-columns: repeat(1, 1fr); }
  .sm-grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
  .sm-grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
  .sm-grid-cols-4 { grid-template-columns: repeat(4, 1fr); }
}

@media (min-width: 768px) {
  .md-grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
  .md-grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
  .md-grid-cols-4 { grid-template-columns: repeat(4, 1fr); }
}

@media (min-width: 1024px) {
  .lg-grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
  .lg-grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
  .lg-grid-cols-4 { grid-template-columns: repeat(4, 1fr); }
  .lg-grid-cols-5 { grid-template-columns: repeat(5, 1fr); }
}

.grid-rows-2 { grid-template-rows: repeat(2, 1fr); }
.grid-flow-col { grid-auto-flow: column; }
.grid-flow-row { grid-auto-flow: row; }

.quanta-hero {
  position: relative;
  width: 100%;
  padding: var(--quanta-space-16) var(--quanta-space-4);
  color: var(--quanta-text-dark);
  background-color: var(--quanta-bg-default);
  background-size: cover;
  background-position: center;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.quanta-hero.fullscreen {
  min-height: 100vh;
}

.quanta-hero-title {
  font-size: var(--quanta-text-5xl);
  font-weight: 700;
  margin-bottom: var(--quanta-space-4);
}

.quanta-hero-sub {
  font-size: var(--quanta-text-xl);
  margin-bottom: var(--quanta-space-6);
  color: var(--quanta-text-muted);
}

.quanta-hero-cta {
  display: inline-block;
  padding: var(--quanta-space-3) var(--quanta-space-6);
  background: var(--quanta-primary);
  color: var(--white);
  border-radius: var(--quanta-rounded-md);
  font-weight: 600;
  transition: background 0.2s ease;
  text-decoration: none;
}

.quanta-hero-cta:hover {
  background: var(--quanta-primary-hover);
}

/* ─────────── Variant 1: Centered ─────────── */
.quanta-hero.centered {
  text-align: center;
  align-items: center;
}

/* ─────────── Variant 2: Split Layout ─────────── */
.quanta-hero.split {
  flex-direction: row;
  gap: var(--quanta-space-12);
  align-items: center;
}

.quanta-hero.split .quanta-hero-content {
  flex: 1;
}

.quanta-hero.split .quanta-hero-image {
  flex: 1;
  min-height: 300px;
}

.quanta-hero.split .quanta-hero-image img {
  width: 100%;
  border-radius: var(--quanta-rounded-md);
}

/* ─────────── Variant 3: Overlay ─────────── */
.quanta-hero.overlay {
  background: url('/path/to/hero-bg.jpg') center/cover no-repeat;
  color: var(--quanta-text-light);
  text-align: center;
}

.quanta-hero.overlay::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  z-index: 1;
}

.quanta-hero.overlay > * {
  position: relative;
  z-index: 2;
}

/* ─────────── Variant 4: Minimal ─────────── */
.quanta-hero.minimal {
  padding: var(--quanta-space-8) var(--quanta-space-4);
  background: var(--quanta-bg-subtle);
  color: var(--quanta-text-default);
}

.quanta-hero.minimal .quanta-hero-title {
  font-size: var(--quanta-text-3xl);
  margin-bottom: var(--quanta-space-2);
}

.quanta-hero.minimal .quanta-hero-sub {
  font-size: var(--quanta-text-md);
  margin-bottom: 0;
}

/* ─────────── Responsive Fixes ─────────── */

@media (max-width: 768px) {
  .quanta-hero-title { font-size: var(--quanta-text-3xl); }
  .quanta-hero-sub { font-size: var(--quanta-text-lg); }
  .quanta-hero.split { flex-direction: column; }
  .quanta-hero.split .quanta-hero-image { order: -1; }
}

html[data-theme="dark"] .quanta-hero {
  color: var(--quanta-text-light);
  background-color: var(--quanta-bg-emphasis);
}

html[data-theme="dark"] .quanta-hero.minimal {
  background-color: var(--quanta-bg-muted);
}

.quanta-input-group {
  display: flex;
  align-items: stretch;
  width: 100%;
  border-radius: var(--quanta-rounded-md);
  overflow: hidden;
  border: var(--quanta-border-width) solid var(--quanta-border-color);
  background-color: var(--white);
}

.quanta-input-icon-left {
  display: flex;
  align-items: center;
  padding: 0 var(--quanta-space-4);
  background: var(--quanta-slate-100);
  color: var(--quanta-text-muted);
  font-size: var(--quanta-text-sm);
}

.quanta-input {
  border: none;
  flex: 1;
  padding: var(--quanta-space-3) var(--quanta-space-3);
  font-size: var(--quanta-text-sm);
  background: transparent;
  color: var(--quanta-text-default);
  font-family: inherit;
}

.quanta-input:focus {
  outline: none;
  background: var(--white);
}

.quanta-input-button {
  background: var(--quanta-primary);
  color: var(--white);
  border: none;
  padding: 0 var(--quanta-space-4);
  cursor: pointer;
  font-size: var(--quanta-text-sm);
  display: flex;
  align-items: center;
  transition: background 0.3s ease;
}

.quanta-input-button:hover {
  background: var(--quanta-primary-hover);
}

/* Dark mode */
html[data-theme="dark"] .quanta-input-group {
  background-color: transparent;
  border-color: var(--quanta-border-color);
}

html[data-theme="dark"] .quanta-input {
  color: var(--quanta-text-light);
}

html[data-theme="dark"] .quanta-input:focus {
  outline: none;
  background: var(--bg-slate-800);
}

html[data-theme="dark"] .quanta-input-icon-left {
  background: var(--quanta-slate-700);
  color: var(--quanta-text-light-muted);
}

html[data-theme="dark"] .quanta-input-button {
  background: var(--quanta-primary);
}

html[data-theme="dark"] .quanta-input-button:hover {
  background: var(--quanta-primary-hover);
}

.lazy-load {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
  will-change: opacity, transform;
}

.lazy-load.show {
  opacity: 1;
  transform: none;
}

/* Direction variants */
.lazy-from-left { transform: translateX(-30px); }
.lazy-from-right { transform: translateX(30px); }
.lazy-from-top { transform: translateY(-30px); }
.lazy-from-bottom { transform: translateY(30px); }

.lazy-from-left.show,
.lazy-from-right.show,
.lazy-from-top.show,
.lazy-from-bottom.show {
  transform: none;
  opacity: 1;
}

.quanta-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ─── Bullet Lists ───────────────────────────── */
.quanta-list-bullets li {
  position: relative;
  padding-left: var(--quanta-space-5);
  margin-bottom: var(--quanta-space-2);
  font-size: var(--quanta-text-base);
  color: var(--quanta-text-default);
}

.quanta-list-bullets li::before {
  content: '•';
  position: absolute;
  left: 0;
  color: var(--quanta-accent-color);
  font-size: var(--quanta-text-lg);
}

.quanta-list-bullets.check li::before {
  content: '✔';
  color: var(--quanta-success);
}

.quanta-list-bullets.dash li::before {
  content: '–';
  color: var(--quanta-text-muted);
}

/* ─── Numbered Lists ─────────────────────────── */
.quanta-list-numbers {
  list-style: decimal;
  padding-left: var(--quanta-space-5);
  font-size: var(--quanta-text-base);
  color: var(--quanta-text-default);
}

.quanta-list-numbers.roman { list-style-type: upper-roman; }
.quanta-list-numbers.alpha { list-style-type: upper-alpha; }

/* ─── List Group (Box Style) ─────────────────── */
.quanta-list-group {
  display: flex;
  flex-direction: column;
  border: var(--quanta-border-width) solid var(--quanta-border-color);
  border-radius: var(--quanta-rounded-md);
  overflow: hidden;
}

.quanta-list-group-item {
  padding: var(--quanta-space-3) var(--quanta-space-4);
  background: var(--quanta-bg-default);
  color: var(--quanta-text-default);
  border-bottom: var(--quanta-border-width) solid var(--quanta-border-color);
  transition: background-color 0.2s;
}

.quanta-list-group-item:last-child {
  border-bottom: none;
}

.quanta-list-group-item:hover {
  background-color: var(--quanta-bg-hover);
  cursor: pointer;
}

/* ─── List Item Icons ───────────────────────── */
.quanta-list-item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-right: var(--quanta-space-2);
  width: 1.25rem;
  height: 1.25rem;
}

.quanta-list-item-icon svg {
  width: 100%;
  height: 100%;
  fill: var(--quanta-primary);
}

/* ─── Tags & Badges ─────────────────────────── */
.quanta-list-tag {
  background: var(--quanta-bg-muted);
  color: var(--quanta-text-muted);
  font-size: var(--quanta-text-xs);
  padding: 0.125rem 0.5rem;
  border-radius: var(--quanta-rounded-sm);
  margin-left: auto;
}

/* ─── Utility Mods ──────────────────────────── */
.quanta-list-spaced li {
  margin-bottom: var(--quanta-space-3);
}

.quanta-list-no-indent li {
  padding-left: 0;
}

/* ─── Dark Mode Support ─────────────────────── */
html[data-theme="dark"] {
  .quanta-list-bullets li,
  .quanta-list-numbers li {
    color: var(--quanta-text-dark);
  }

  .quanta-list-group-item {
    background: var(--quanta-bg-dark-default);
    color: var(--quanta-text-dark);
    border-color: var(--quanta-border-dark-color);
  }

  .quanta-list-group-item:hover {
    background: var(--quanta-bg-dark-hover);
  }

  .quanta-list-tag {
    background: var(--quanta-bg-dark-muted);
    color: var(--quanta-text-muted);
  }
}

.quanta-megamenu {
  position: relative;
}

.quanta-megamenu-toggle {
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: var(--quanta-space-2);
}

.quanta-megamenu-content {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  min-width: 320px;
  max-width: 100vw;
  overflow-x: auto;
  background-color: var(--white);
  color: var(--quanta-text-default);
  padding: var(--quanta-space-6);
  box-shadow: var(--quanta-shadow-lg);
  border-radius: var(--quanta-rounded-md);
  z-index: var(--quanta-z-lg);
  transition: all var(--quanta-duration-normal) var(--quanta-ease-default);
}

/* Show menu */
.quanta-megamenu.show .quanta-megamenu-content {
  display: block;
}

/* Positioning Modifiers */
.quanta-megamenu-start .quanta-megamenu-content {
  left: 0;
  right: auto;
}

.quanta-megamenu-center .quanta-megamenu-content {
  left: 50%;
  transform: translateX(-50%);
}

.quanta-megamenu-end .quanta-megamenu-content {
  right: 0;
  left: auto;
}

/* Layout Containers */
.quanta-megamenu-columns {
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  gap: var(--quanta-space-6);
  min-width: 100%;
}

.quanta-megamenu-row {
  flex-direction: row !important;
  flex-wrap: wrap;
}

/* Column Item */
.quanta-megamenu-col {
  flex: 1 1 220px;
  min-width: 220px;
}

.quanta-megamenu-heading {
  font-size: var(--quanta-text-base);
  font-weight: 600;
  margin-bottom: var(--quanta-space-2);
}

.quanta-megamenu-item {
  display: block;
  padding: var(--quanta-space-2) 0;
  font-size: var(--quanta-text-sm);
  color: var(--quanta-text-default);
  text-decoration: none;
  transition: color 0.2s ease;
}

.quanta-megamenu-item:hover {
  color: var(--quanta-primary);
}

/* Width Modifiers */
.quanta-megamenu-content.w-xs { width: var(--quanta-width-xs); }
.quanta-megamenu-content.w-sm { width: var(--quanta-width-sm); }
.quanta-megamenu-content.w-md { width: var(--quanta-width-md); }
.quanta-megamenu-content.w-lg { width: var(--quanta-width-lg); }
.quanta-megamenu-content.w-xl { width: var(--quanta-width-xl); }
.quanta-megamenu-content.w-full { width: 100%; }
.quanta-megamenu-content.w-auto { width: auto; }

/* Animation */
.quanta-megamenu-content.fade-in {
  animation: quanta-fade-in 0.3s ease-in-out both;
}

@keyframes quanta-fade-in {
  from {
    opacity: 0;
    transform: translateY(-0.5rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Dark Mode */
html[data-theme="dark"] .quanta-megamenu-content {
  background-color: var(--quanta-slate-800);
  color: var(--quanta-text-light);
  box-shadow: var(--quanta-shadow-md);
}

html[data-theme="dark"] .quanta-megamenu-item:hover {
  color: var(--quanta-primary);
}

/* Mobile Layout */

@media (max-width: 640px) {
  .quanta-megamenu-content {
    position: static;
    width: 100%;
    max-height: none;
    transform: none;
    box-shadow: none;
    border-radius: 0;
    padding: var(--quanta-space-4);
  }

  .quanta-megamenu-columns {
    flex-direction: column !important;
  }
}

.quanta-modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.6);
  z-index: 9999;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--quanta-transition-fast);
}

.quanta-modal-backdrop.active {
  opacity: 1;
  pointer-events: auto;
}

/* ─── Modal Base ─────────────────────────────── */
.quanta-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0.95);
  background-color: var(--quanta-bg-default);
  color: var(--quanta-text-default);
  border-radius: var(--quanta-rounded-md);
  box-shadow: var(--quanta-shadow-xl);
  width: 90%;
  max-width: 32rem;
  z-index: 10000;
  display: flex;
  flex-direction: column;
  opacity: 0;
  pointer-events: none;
  transition: all var(--quanta-transition-normal) ease;
  padding: var(--quanta-space-4);
  gap: var(--quanta-space-4)
}

.quanta-modal.active {
  opacity: 1;
  pointer-events: auto;
  transform: translate(-50%, -50%) scale(1);
}

.quanta-modal-header {
  font-size: var(--quanta-text-md);
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.quanta-modal-body {
  font-size: var(--quanta-body-size);
  line-height: var(--quanta-body-line-height);
  color: var(--quanta-text-default);
}

.quanta-modal-footer {
  display: flex;
  gap: var(--quanta-space-2);
}

.quanta-modal-footer.footer-end{
  justify-content: flex-end;
}

.quanta-modal-footer.footer-start{
  justify-content: flex-start;
}

.quanta-modal-footer.footer-center{
  justify-content: flex-start;
}

/* ─── Close Button ───────────────────────────── */
.quanta-modal-close {
  background: none;
  border: none;
  font-size: var(--quanta-text-lg);
  cursor: pointer;
  color: var(--quanta-text-default);
  padding: var(--quanta-space-2);
  border-radius: var(--quanta-space-2);
}

.quanta-modal-close:hover {
  color: var(--quanta-primary);
}

/* ─── Dark Mode ──────────────────────────────── */
html[data-theme="dark"] {
  .quanta-modal {
    background-color: var(--quanta-slate-800);
    color: var(--quanta-text-light);
    box-shadow: var(--quanta-shadow-2xl);
  }

  .quanta-modal-header,
  .quanta-modal-footer {
    border-color: var(--quanta-border-dark);
  }

  .quanta-modal-close:hover {
    color: var(--quanta-primary-light);
  }
}

/* ─── Responsive Sizes ───────────────────────── */

@media (min-width: 600px) {
  .quanta-modal {
    width: 85%;
    padding: var(--quanta-space-6);
  }

  .quanta-modal-header {
    font-size: var(--quanta-heading-size-md);
  }

  .quanta-modal-body {
    font-size: var(--quanta-body-size-md);
  }
}

@media (min-width: 768px) {
  .quanta-modal {
    width: 70%;
    max-width: 36rem;
  }

  .quanta-modal-header {
    font-size: var(--quanta-heading-size-lg);
  }

  .quanta-modal-body {
    font-size: var(--quanta-body-size-lg);
  }
}

@media (min-width: 1024px) {
  .quanta-modal {
    width: 60%;
    max-width: 40rem;
  }

  .quanta-modal-header {
    font-size: var(--quanta-heading-size-xl);
  }

  .quanta-modal-body {
    font-size: var(--quanta-body-size-xl);
  }
}

@media (min-width: 1280px) {
  .quanta-modal {
    width: 45%;
    max-width: 44rem;
  }

  .quanta-modal-header {
    font-size: var(--quanta-heading-size-2xl);
  }

  .quanta-modal-body {
    font-size: var(--quanta-body-size-2xl);
  }
}

@media (min-width: 1600px) {
  .quanta-modal {
    width: 35%;
    max-width: 48rem;
  }

  .quanta-modal-header {
