/* ─── Dark Mode ─────────────────────────────────────── */
html[data-theme="dark"] .quanta-navbar {
  background: var(--quanta-slate-900);
}

html[data-theme="dark"] .quanta-nav-link,
html[data-theme="dark"] .quanta-brand {
