}

.quanta-pagination-no-wrap {
  flex-wrap: nowrap;
}

.quanta-pagination-wrap {
  flex-wrap: wrap;
}

/* Responsive Wrapping */

@media (max-width: 640px) {
  .quanta-pagination-wrap {
    flex-wrap: wrap;
  }
}

/* Pagination Size Utility Classes */
.quanta-pagination-small .quanta-pagination-link {
  padding: var(--quanta-space-1) var(--quanta-space-2);
  font-size: var(--quanta-text-sm);
}

.quanta-pagination-large .quanta-pagination-link {
  padding: var(--quanta-space-3) var(--quanta-space-6);
  font-size: var(--quanta-text-lg);
}

/* ─── Icon Styles for Pagination (for First, Previous, Next, Last) ─── */
.quanta-pagination-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.quanta-pagination-prev-icon,
.quanta-pagination-next-icon,
