  color: var(--quanta-bg-info);
}

.quanta-rating.secondary .quanta-rating-star.filled,
.quanta-rating.secondary .quanta-rating-star.half::before {
  color: var(--quanta-bg-secondary);
}

.quanta-rating.neutral .quanta-rating-star.filled,
.quanta-rating.neutral .quanta-rating-star.half::before {
  color: var(--quanta-bg-neutral);
}

.quanta-rating.accent .quanta-rating-star.filled,
.quanta-rating.accent .quanta-rating-star.half::before {
