/* ─── Dark Mode ─────────────────────────────── */
html[data-theme="dark"] .quanta-rating-star {
  color: var(--quanta-slate-600);
}

html[data-theme="dark"] .quanta-rating.primary .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.primary .quanta-rating-star.half::before {
  color: var(--quanta-primary);
}

html[data-theme="dark"] .quanta-rating.success .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.success .quanta-rating-star.half::before {
  color: var(--quanta-bg-success);
}

html[data-theme="dark"] .quanta-rating.warning .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.warning .quanta-rating-star.half::before {
  color: var(--quanta-bg-warning);
}

html[data-theme="dark"] .quanta-rating.danger .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.danger .quanta-rating-star.half::before {
  color: var(--quanta-bg-danger);
}

html[data-theme="dark"] .quanta-rating.info .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.info .quanta-rating-star.half::before {
  color: var(--quanta-bg-info);
}

html[data-theme="dark"] .quanta-rating.secondary .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.secondary .quanta-rating-star.half::before {
  color: var(--quanta-bg-secondary);
}

html[data-theme="dark"] .quanta-rating.neutral .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.neutral .quanta-rating-star.half::before {
  color: var(--quanta-bg-neutral);
}

html[data-theme="dark"] .quanta-rating.accent .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.accent .quanta-rating-star.half::before {
  color: var(--quanta-bg-accent);
}

html[data-theme="dark"] .quanta-rating.ghost .quanta-rating-star.filled,
html[data-theme="dark"] .quanta-rating.ghost .quanta-rating-star.half::before {
  color: var(--quanta-text-ghost);
}

