.quanta-skeleton {
  position: relative;
  display: inline-block;
  background-color: var(--quanta-slate-200);
  animation: quanta-opacity 1.5s infinite ease-in-out;
  border-radius: var(--quanta-rounded-md);
  overflow: hidden;
}

.quanta-skeleton::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.2),
    transparent
  );
  animation: quanta-skeleton-wave 1.6s infinite;
}

/* ─── Presets ─────────────────────────── */
.quanta-skeleton-text {
  height: var(--quanta-space-6);
  width: 100%;
  margin-bottom: var(--quanta-space-2);
}

.quanta-skeleton-title {
  height: var(--quanta-space-8);
  width: 75%;
  margin-bottom: var(--quanta-space-3);
}

.quanta-skeleton-circle {
  width: var(--quanta-space-10);
  height: var(--quanta-space-10);
  border-radius: 50%;
}

.quanta-skeleton-avatar-sm {
  width: var(--quanta-space-8);
  height: var(--quanta-space-8);
  border-radius: 50%;
}

.quanta-skeleton-rect {
  width: 100%;
  height: 120px;
}

.quanta-skeleton-block {
  width: 100%;
  height: 200px;
}

.quanta-skeleton-btn {
  width: 160px;
  height: calc(var(--quanta-space-8) + var(--quanta-space-4));
  border-radius: var(--quanta-rounded-sm);
}

/* ─── Animations ───────────────────────── */

@keyframes quanta-opacity {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.4; transform: scale(1);}
}

@keyframes quanta-skeleton-wave {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

/* ─── Responsive Adjustments ───────────── */

@media (max-width: 640px) {
  .quanta-skeleton-text { height: var(--quanta-space-3); }
  .quanta-skeleton-title { width: 90%; }
  .quanta-skeleton-btn { width: 100px; height: var(--quanta-space-7); }
}

/* ─── Dark Mode Support ───────────────── */
html[data-theme="dark"] .quanta-skeleton {
  background-color: var(--quanta-slate-700);
}

html[data-theme="dark"] .quanta-skeleton::before {
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.1),
    transparent
  );
}

/* ─── Quanta Spinners ───────────────────────────────────────────── */

.quanta-spinner {
  display: inline-block;
  border: 3px solid var(--quanta-border-color);
  border-top: 3px solid var(--quanta-primary);
  border-radius: 50%;
  animation: quanta-spin 1s linear infinite;
}

/* ─── Spinner Sizes ───────────────────────────────────────────── */
.quanta-spinner.sm { width: 32px; height: 32px; }
.quanta-spinner.md { width: 48px; height: 48px; }
.quanta-spinner.lg { width: 64px; height: 64px; }

/* ─── Dual Ring Spinner ──────────────────────────────────────── */
.quanta-spinner-dual-ring {
  display: inline-block;
  width: 48px;
  height: 48px;
}
.quanta-spinner-dual-ring:after {
  content: " ";
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 3px solid var(--quanta-border-color);
  border-color: var(--quanta-primary) transparent var(--quanta-primary) transparent;
  animation: quanta-spin 1.2s linear infinite;
}

/* ─── Dot Spinner ────────────────────────────────────────────── */
.quanta-spinner-dots {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--quanta-space-2);
}

.quanta-spinner-dots .dot {
  width: 10px;
  height: 10px;
  background-color: var(--quanta-primary);
  border-radius: 50%;
  animation: quanta-bounce 0.8s infinite ease-in-out;
}

.quanta-spinner-dots .dot:nth-child(2) {
  animation-delay: 0.1s;
}

.quanta-spinner-dots .dot:nth-child(3) {
  animation-delay: 0.2s;
}

/* ─── Pulse Spinner ──────────────────────────────────────────── */
.quanta-spinner-pulse {
  width: 40px;
  height: 40px;
  background-color: var(--quanta-primary);
  border-radius: 50%;
  animation: quanta-pulse 1s ease-in-out infinite;
}

/* ─── Bar Spinner ────────────────────────────────────────────── */
.quanta-spinner-bar {
  width: 100%;
  height: 8px;
  background-color: var(--quanta-slate-100);
  border-radius: var(--quanta-rounded-md);
  position: relative;
  overflow: hidden;
}

.quanta-spinner-bar .quanta-bar {
  position: absolute;
  height: 100%;
  width: 40%;
  background-color: var(--quanta-primary);
  animation: quanta-loading-bar 1.5s ease-in-out infinite;
}

/* ─── Semantic Color Overrides ───────────────────────────── */

.quanta-spinner.success,
.quanta-spinner-dual-ring.success,
.quanta-spinner-dots.success .dot,
.quanta-spinner-pulse.success,
.quanta-spinner-bar.success .quanta-bar {
