.quanta-spinner.warning,
.quanta-spinner-dual-ring.warning,
.quanta-spinner-dots.warning .dot,
.quanta-spinner-pulse.warning,
.quanta-spinner-bar.warning .quanta-bar {
  --quanta-primary: var(--quanta-bg-warning);
}

.quanta-spinner.danger,
.quanta-spinner-dual-ring.danger,
.quanta-spinner-dots.danger .dot,
.quanta-spinner-pulse.danger,
.quanta-spinner-bar.danger .quanta-bar {
  --quanta-primary: var(--quanta-bg-danger);
}

.quanta-spinner.info,
.quanta-spinner-dual-ring.info,
.quanta-spinner-dots.info .dot,
.quanta-spinner-pulse.info,
.quanta-spinner-bar.info .quanta-bar {
  --quanta-primary: var(--quanta-bg-info);
}

.quanta-spinner.secondary,
.quanta-spinner-dual-ring.secondary,
.quanta-spinner-dots.secondary .dot,
.quanta-spinner-pulse.secondary,
.quanta-spinner-bar.secondary .quanta-bar {
  --quanta-primary: var(--quanta-bg-secondary);
}

.quanta-spinner.accent,
.quanta-spinner-dual-ring.accent,
.quanta-spinner-dots.accent .dot,
.quanta-spinner-pulse.accent,
.quanta-spinner-bar.accent .quanta-bar {
  --quanta-primary: var(--quanta-bg-accent);
}

.quanta-spinner.neutral,
.quanta-spinner-dual-ring.neutral,
.quanta-spinner-dots.neutral .dot,
.quanta-spinner-pulse.neutral,
.quanta-spinner-bar.neutral .quanta-bar {
  --quanta-primary: var(--quanta-bg-neutral);
}

/* ─── Keyframes ──────────────────────────────────────────────── */

@keyframes quanta-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes quanta-bounce {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.5); opacity: 0.6; }
}

@keyframes quanta-pulse {
  0% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.2); opacity: 0.5; }
  100% { transform: scale(1); opacity: 1; }
}

@keyframes quanta-loading-bar {
  0% { left: -40%; }
  100% { left: 100%; }
}

/* ─── Dark Mode Support ─────────────────────────────────────── */

html[data-theme="dark"] {
  .quanta-spinner {
    border-color: var(--quanta-border-color);
    border-top-color: var(--quanta-primary);
  }

  .quanta-spinner-dual-ring:after {
    border-color: var(--quanta-primary) transparent var(--quanta-primary) transparent;
  }

  .quanta-spinner-bar {
    background-color: var(--quanta-slate-800);
  }

  .quanta-spinner-bar .quanta-bar {
    background-color: var(--quanta-primary);
  }

  .quanta-spinner-dots .dot,
  .quanta-spinner-pulse {
    background-color: var(--quanta-primary);
  }
}

/* ─── Responsive Sizing ─────────────────────────────────────── */

@media (max-width: 640px) {
  .quanta-spinner.sm { width: 24px; height: 24px; }
  .quanta-spinner.md { width: 36px; height: 36px; }
  .quanta-spinner.lg { width: 48px; height: 48px; }
}

@media (min-width: 641px) and (max-width: 768px) {
  .quanta-spinner.sm { width: 28px; height: 28px; }
  .quanta-spinner.md { width: 42px; height: 42px; }
  .quanta-spinner.lg { width: 56px; height: 56px; }
}

@media (min-width: 769px) {
  .quanta-spinner.sm { width: 32px; height: 32px; }
  .quanta-spinner.md { width: 48px; height: 48px; }
  .quanta-spinner.lg { width: 64px; height: 64px; }
}

.quanta-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--quanta-space-6);
  align-items: stretch;
  justify-content: center;
  padding: var(--quanta-space-4);
}

.quanta-stat {
  background: var(--white);
  border-radius: var(--quanta-rounded-md);
  padding: var(--quanta-space-6) var(--quanta-space-5);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: background 0.3s ease, transform 0.2s ease;
}

.quanta-stat:hover {
  transform: translateY(-4px);
  box-shadow: var(--quanta-shadow-md);
}

.quanta-stat-icon {
  font-size: var(--quanta-text-3xl);
  margin-bottom: var(--quanta-space-2);
  color: var(--quanta-primary);
}

.quanta-stat-value {
  font-size: var(--quanta-text-4xl);
  font-weight: 700;
  color: var(--quanta-text-strong);
  margin-bottom: var(--quanta-space-1);
}

.quanta-stat-label {
  font-size: var(--quanta-text-sm);
  color: var(--quanta-text-muted);
}

.quanta-stat-variation {
  font-size: var(--quanta-text-xs);
  font-weight: 500;
  color: var(--quanta-success);
  margin-top: var(--quanta-space-1);
}

/* ─── Variants ───────────────────────────────────────────── */
.quanta-stat.danger .quanta-stat-variation { color: var(--quanta-danger); }
.quanta-stat.warning .quanta-stat-variation { color: var(--quanta-warning); }
.quanta-stat.info .quanta-stat-variation { color: var(--quanta-info); }

/* ─── Dark Mode ─────────────────────────────────────────── */
html[data-theme="dark"] .quanta-stat {
  background: var(--quanta-bg-emphasis);
  color: var(--quanta-text-light);
}

html[data-theme="dark"] .quanta-stat-label {
  color: var(--quanta-grey-400);
}

html[data-theme="dark"] .quanta-stat:hover {
  background: var(--quanta-slate-800);
}

/* ─── Responsive Fine-Tuning ────────────────────────────── */

@media (max-width: 640px) {
  .quanta-stat {
    padding: var(--quanta-space-4);
  }

  .quanta-stat-value {
    font-size: var(--quanta-text-2xl);
  }
}

.quanta-stepper,
.quanta-stepper-line {
  display: flex;
  align-items: center;
  font-family: var(--quanta-font-primary);
  position: relative;
  width: 100%;
}

.quanta-stepper-line {
  justify-content: space-between;
  padding: var(--quanta-space-2) 0;
}

.quanta-stepper-line .quanta-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  position: relative;
  text-align: center;
}

.quanta-stepper-line .quanta-step-icon {
  width: 1rem;
  height: 1rem;
  border-radius: var(--quanta-rounded-full);
  background-color: var(--quanta-border-color);
  border: 2px solid var(--quanta-border-color);
  z-index: 1;
}

.quanta-stepper-line .quanta-step-label {
  margin-top: var(--quanta-space-2);
  font-size: var(--quanta-text-sm);
  color: var(--quanta-text-default);
}

.quanta-stepper-line .quanta-step:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 0.5rem;
  left: 50%;
  height: 2px;
  width: 100%;
  background-color: var(--quanta-border-color);
  z-index: 0;
  transform: translateX(0);
}

.quanta-stepper-line .quanta-step[data-status="completed"]::after {
  background-color: var(--quanta-primary);
}

.quanta-step[data-status="completed"] .quanta-step-icon {
  background-color: var(--quanta-primary);
  border-color: var(--quanta-primary);
}

.quanta-step[data-status="active"] .quanta-step-icon {
  background-color: var(--quanta-bg-default);
  border-color: var(--quanta-primary);
}

.quanta-step[data-status="active"] .quanta-step-label {
  color: var(--quanta-primary);
}

.quanta-step[data-status="upcoming"] .quanta-step-icon {
  background-color: var(--quanta-border-color);
  border-color: var(--quanta-border-color);
}

.quanta-step[data-status="upcoming"] .quanta-step-label {
  color: var(--quanta-slate-400);
}

html[data-theme="dark"] .quanta-stepper-line .quanta-step-icon {
  background-color: var(--quanta-slate-700);
  border-color: var(--quanta-slate-700);
}

html[data-theme="dark"] .quanta-step[data-status="completed"] .quanta-step-icon {
  background-color: var(--quanta-primary);
  border-color: var(--quanta-primary);
}

html[data-theme="dark"] .quanta-step[data-status="completed"]::after {
  background-color: var(--quanta-primary);
}

html[data-theme="dark"] .quanta-step[data-status="active"] .quanta-step-icon {
  background-color: var(--quanta-bg-default);
  border-color: var(--quanta-primary);
}

html[data-theme="dark"] .quanta-step[data-status="upcoming"] .quanta-step-label {
  color: var(--quanta-slate-500);
}

.sticky {
  position: sticky;
  z-index: var(--quanta-z-md, 10);
}

.sticky-x {
  position: sticky;
}

.sticky-y {
  position: sticky;
}

.sticky-top {
  top: 0;
}

.sticky-bottom {
  bottom: 0;
}

.sticky-left {
  left: 0;
}

.sticky-right {
  right: 0;
}

/* ─── Quanta spacing values ───────────────────────────── */
.top-0    { top: 0; }
.top-1    { top: var(--quanta-space-1); }
.top-2    { top: var(--quanta-space-2); }
.top-4    { top: var(--quanta-space-4); }
.top-6    { top: var(--quanta-space-6); }
.top-8    { top: var(--quanta-space-8); }
.top-12   { top: var(--quanta-space-12); }
.top-16   { top: var(--quanta-space-16); }

.bottom-0  { bottom: 0; }
.bottom-2  { bottom: var(--quanta-space-2); }
.bottom-4  { bottom: var(--quanta-space-4); }
.bottom-8  { bottom: var(--quanta-space-8); }

.left-0   { left: 0; }
.left-2   { left: var(--quanta-space-2); }
.left-4   { left: var(--quanta-space-4); }

.right-0  { right: 0; }
.right-2  { right: var(--quanta-space-2); }
.right-4  { right: var(--quanta-space-4); }

/* ─── Responsive Sticky ───────────────────────────── */

@media (min-width: 640px) {
  .sm-sticky     { position: sticky; }
  .sm-top-0      { top: 0; }
  .sm-top-4      { top: var(--quanta-space-4); }
  .sm-left-0     { left: 0; }
}

@media (min-width: 768px) {
  .md-sticky     { position: sticky; }
  .md-top-0      { top: 0; }
  .md-top-6      { top: var(--quanta-space-6); }
  .md-right-0    { right: 0; }
}

@media (min-width: 1024px) {
  .lg-sticky     { position: sticky; }
  .lg-top-8      { top: var(--quanta-space-8); }
}

@media (min-width: 1280px) {
  .xl-sticky     { position: sticky; }
}

/* ─── Overflow helpers (for parent containers) ───── */
.sticky-container {
  overflow-y: auto;
  max-height: 100vh;
}

.quanta-table-responsive {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  margin-block: var(--quanta-space-4);
}

/* ─── Base Table ─────────────────────────────────────── */
.quanta-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--quanta-text-sm);
  color: var(--quanta-text-default);
}

.quanta-table th,
.quanta-table td {
  padding: var(--quanta-space-3);
  text-align: left;
  border-bottom: 1px solid var(--quanta-border-color);
  vertical-align: top;
}

.quanta-table th {
  font-weight: 600;
  color: var(--quanta-text-default);
}

/* ─── Size Variants ─────────────────────────────────── */
.quanta-table-sm th,
.quanta-table-sm td {
  padding: var(--quanta-space-2);
  font-size: var(--quanta-text-xs);
}

.quanta-table-lg th,
.quanta-table-lg td {
  padding: var(--quanta-space-4);
  font-size: var(--quanta-text-base);
}

/* ─── Visual Variants ───────────────────────────────── */
.quanta-table-hover tbody tr:hover {
  background-color: var(--quanta-slate-100);
}

.quanta-table-zebra tbody tr:nth-child(odd) {
  background-color: var(--quanta-slate-50);
}

.quanta-table-bordered th,
.quanta-table-bordered td {
  border: 1px solid var(--quanta-border-color);
}

.quanta-table-rounded {
  border-radius: var(--quanta-rounded-md);
  overflow: hidden;
}

.quanta-table-clean th,
.quanta-table-clean td {
  border: none !important;
  background-color: transparent;
}

.quanta-table-shadowed {
  box-shadow: var(--quanta-shadow-md);
}

.quanta-table-glass {
  background-color: var(--quanta-slate-50);
  backdrop-filter: blur(6px);
  border-radius: var(--quanta-rounded-lg);
  overflow: hidden;
}

/* ─── Sortable Headers ─────────────────────────────── */
.quanta-table th.sortable {
  position: relative;
  cursor: pointer;
  user-select: none;
}

.quanta-table th.sortable::after {
  content: '';
  position: absolute;
  right: var(--quanta-space-2);
  top: 50%;
  transform: translateY(-50%);
  border: 5px solid transparent;
  border-top-color: var(--quanta-text-muted);
  opacity: 0.6;
  transition: transform 0.3s ease;
}

.quanta-table th.sortable.sorted-asc::after {
  transform: translateY(-50%) rotate(180deg);
}

.quanta-table th.sortable.sorted-desc::after {
  transform: translateY(-50%) rotate(0);
}

/* ─── Pagination Controls ───────────────────────────── */
.quanta-pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--quanta-space-2);
  width: 100%;
  margin-top: var(--quanta-space-4);
}

.quanta-pagination-button {
  padding: var(--quanta-space-2) var(--quanta-space-3);
  font-size: var(--quanta-text-sm);
  background-color: var(--quanta-slate-100);
  color: var(--quanta-text-default);
  border: none;
  border-radius: var(--quanta-rounded-md);
  cursor: pointer;
  transition: background-color 0.2s, color 0.2s;
}

.quanta-pagination-button:hover {
  background-color: var(--quanta-slate-200);
  color: var(--quanta-text-dark);
}

.quanta-pagination-button.active {
  background-color: var(--quanta-primary);
  color: var(--white);
}

.quanta-pagination-button:disabled {
  background-color: var(--quanta-slate-50);
  color: var(--quanta-text-muted);
  cursor: not-allowed;
}

/* ─── Dark Mode ─────────────────────────────────────── */
html[data-theme="dark"] {
  .quanta-table {
    color: var(--quanta-text-light);
  }

  .quanta-table th {
    color: var(--quanta-text-light);
  }

  .quanta-table-hover tbody tr:hover {
    background-color: var(--quanta-slate-800);
  }

  .quanta-table-zebra tbody tr:nth-child(odd) {
    background-color: var(--quanta-slate-900);
  }

  .quanta-table-clean th,
  .quanta-table-clean td {
    color: var(--quanta-text-light);
  }

  .quanta-table-glass {
    background-color: var(--quanta-slate-700);
  }

  .quanta-table-bordered th,
  .quanta-table-bordered td {
    border-color: var(--quanta-border-color);
  }

  .quanta-pagination-button {
    background-color: var(--quanta-slate-800);
    color: var(--quanta-text-light);
  }

  .quanta-pagination-button:hover {
    background-color: var(--quanta-slate-700);
    color: var(--quanta-text-light);
  }

  .quanta-pagination-button.active {
    background-color: var(--quanta-primary);
    color: var(--white);
  }
}

.quanta-textarea-wrapper {
  display: flex;
  flex-direction: column;
  position: relative;
  width: 100%;
}

.quanta-textarea {
  padding: var(--quanta-space-2) var(--quanta-space-3);
  border: var(--quanta-border-width) solid var(--quanta-border-color);
  border-radius: var(--quanta-rounded-md);
  resize: vertical;
  min-height: 100px;
  font-size: var(--quanta-text-sm);
  font-family: inherit;
  background: var(--white);
  color: var(--quanta-text-default);
  transition: border-color 0.3s ease;
  padding-bottom: var(--quanta-space-8);
}

.quanta-textarea:focus {
  border-color: var(--quanta-primary);
  outline: none;
  box-shadow: 0 0 0 2px var(--quanta-primary);
}

.quanta-char-count {
  font-size: var(--quanta-text-xs);
  color: var(--black);
  text-align: right;
  padding: var(--quanta-space-2) var(--quanta-space-4);
  border-radius: var(--quanta-rounded-md);
  background: var(--quanta-border-color);
  position: absolute;
  bottom: 4px;
  right: 4px;
}

html[data-theme="dark"] .quanta-textarea {
  background-color: transparent;
  border-color: var(--quanta-border-color);
  color: var(--quanta-text-light);
}

html[data-theme="dark"] .quanta-char-count {
  color: var(--white);
}

.quanta-tabs {
  display: flex;
  flex-wrap: wrap;
  justify-content: start;
  gap: var(--quanta-space-4);
  border-bottom: var(--quanta-border-width) solid var(--quanta-border-color);
  width: 100%;
}

.quanta-tab {
  background: transparent;
  padding: var(--quanta-space-3) var(--quanta-space-5);
  font-size: var(--quanta-body-size-md);
  font-weight: 500;
  color: var(--quanta-text-muted);
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
}

.quanta-tab:hover {
  color: var(--quanta-text-default);
}

.quanta-tab.active {
  color: var(--quanta-text-default);
  border-bottom-color: var(--quanta-primary);
  font-weight: 600;
}

.quanta-tab-content {
  width: 100%;
  padding: var(--quanta-space-5) 0;
}

.quanta-tab-panel {
  display: none;
  animation: quanta-fade 0.3s ease;
}

.quanta-tab-panel.active {
  display: block;
}

@keyframes quanta-fade {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Dark Mode */
html[data-theme="dark"] {
  .quanta-tabs {
    border-color: var(--quanta-border-color);
  }
  .quanta-tab {
    color: var(--quanta-grey-400);
  }
  .quanta-tab.active {
    color: var(--quanta-text-light);
    border-color: var(--quanta-primary);
  }
}

/* Mobile */

@media (max-width: 768px) {
  .quanta-tabs {
    flex-direction: column;
    align-items: stretch;
  }
  .quanta-tab {
    width: 100%;
    text-align: center;
  }
}

.quanta-theme-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--quanta-space-2);
  padding: var(--quanta-space-2);
  border: none;
  background: var(--white);
  color: var(--quanta-text-default);
  border-radius: var(--quanta-rounded-lg);
  border: 2px solid var(--quanta-border-color);
  cursor: pointer;
  transition: background 0.3s;
  height: fit-content;
  width: fit-content;
}

.quanta-theme-toggle:hover {
  background: var(--quanta-bg-hover);
}

.quanta-theme-toggle .icon-sun,
.quanta-theme-toggle .icon-moon {
  width: fit-content;
  height: fit-content;
  display: flex;
}

html[data-theme="dark"] .quanta-theme-toggle {
  background: var(--quanta-slate-800);
  border-color: var(--quanta-border-color);
}

html[data-theme="dark"] .quanta-theme-toggle .icon-sun {
  display: none;
}

html[data-theme="light"] .quanta-theme-toggle .icon-moon {
  display: none;
}

.quanta-timeline {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--quanta-space-8);
  border-left: 3px solid var(--quanta-border-color);
}

.quanta-timeline-item {
  position: relative;
  padding-left: var(--quanta-space-6);
  transition: all 0.3s ease;
}

.quanta-timeline-item::before {
  content: '';
  position: absolute;
  left: -0.5rem;
  width: 0.9rem;
  height: 0.9rem;
  background-color: var(--quanta-primary);
  border-radius: 50%;
  box-shadow: 0 0 0 4px var(--quanta-bg-default);
  z-index: 1;
}

.quanta-timeline-item.quanta-beginning::before {
  content: '';
  position: absolute;
  left: -0.4rem;
  width: var(--quanta-space-3);
  height: var(--quanta-space-3);
  background-color: var(--quanta-bg-default);
  border: 1px solid var(--quanta-primary);
  border-radius: 50%;
  box-shadow: 0 0 0 4px var(--white);
  z-index: 1;
}

.quanta-timeline-icon {
  font-size: var(--quanta-text-lg);
  margin-right: var(--quanta-space-2);
  color: var(--quanta-primary);
}

.quanta-timeline .quanta-time {
  font-size: var(--quanta-text-sm);
  color: var(--quanta-text-muted);
  margin-bottom: var(--quanta-space-1);
}

.quanta-timeline .quanta-title {
  font-size: var(--quanta-text-lg);
  font-weight: 600;
  color: var(--quanta-text-strong);
  margin-bottom: var(--quanta-space-1);
}

.quanta-timeline .quanta-content {
  font-size: var(--quanta-body-size);
  color: var(--quanta-text-default);
}

/* Alternate timeline on larger screens */

@media (min-width: 768px) {
  .quanta-timeline {
    padding-left: 0;
  }

  .quanta-timeline-item {
    width: 50%;
  }
}

/* Dark Mode Support */
html[data-theme="dark"] {
  .quanta-timeline-item::before {
    box-shadow: 0 0 0 4px var(--quanta-slate-900);
  }

  .quanta-timeline-item.quanta-beginning::before {
    background: var(--quanta-slate-900);
  }

  .quanta-timeline-item {
    color: var(--quanta-text-light);
  }

  .quanta-timeline .quanta-title {
    color: var(--quanta-text-light);
  }

  .quanta-timeline .quanta-time {
    color: var(--quanta-grey-400);
  }

  .quanta-timeline .quanta-content {
    color: var(--quanta-grey-200);
  }
}

.quanta-tooltip {
  position: absolute;
  max-width: 200px;
  background: var(--quanta-slate-800);
  color: var(--white);
  padding: 0.5rem 0.75rem;
  font-size: var(--quanta-text-sm);
  border-radius: var(--quanta-rounded-md);
  box-shadow: var(--quanta-shadow-md);
  pointer-events: none;
  opacity: 0;
  transform: translateY(-6px);
  transition: opacity 0.2s ease, transform 0.2s ease;
  white-space: nowrap;
  z-index: var(--quanta-z-tooltip, 9999);
}

.quanta-tooltip.show {
  opacity: 1;
  transform: translateY(0);
}

.quanta-tooltip::after {
  content: "";
  position: absolute;
  bottom: -16px;
  left: 50%;
  transform: translateX(-50%);
  border-width: 8px;
  border-style: solid;
  border-color: var(--quanta-slate-800) transparent transparent transparent;
}

/* Size variants */
.tooltip-sm { font-size: 0.6875rem; padding: 0.25rem 0.5rem; }
.tooltip-md { /* default */ }
.tooltip-lg { font-size: 0.875rem; padding: 0.75rem 1rem; }

/* Dark mode overrides */
html[data-theme="dark"]{
  .quanta-tooltip {
    background: var(--white);
    color: var(--black);
  }

  .quanta-tooltip::after {
    border-color: var(--white) transparent transparent transparent;
  }
}

.visible { visibility: visible; }
.invisible { visibility: hidden; }

/* Display toggle */
.hidden { display: none !important; }
.block { display: block !important; }
.inline { display: inline !important; }
.inline-block { display: inline-block !important; }

/* Screen-only / Print-only */
.screen-only { display: block; }
.print-only { display: none; }

@media print {
  .screen-only { display: none !important; }
  .print-only { display: block !important; }
}

/* ─── Responsive Display ───────────────────── */

@media (max-width: 640px) {
